function worldMapDefine.getRealOffset(lv, model)
	local offset = cc.p(0, 0)
	if model then
		for k, v in pairs(worldMapDefine.castlePreViewOffset) do
			if v.model and model >= v.model[1] and model <= v.model[2] then
				offset = v.offset
				break
			end
		end
	elseif 40 <= lv then
		local warLv = math.floor((lv - 30) / 10)
		for k, v in pairs(worldMapDefine.castlePreViewOffset) do
			if v.warLv and warLv >= v.warLv[1] and warLv <= v.warLv[2] then
				offset = v.offset
				break
			end
		end
	else
		lv = math.min(30, lv)
		for k, v in pairs(worldMapDefine.castlePreViewOffset) do
			if v.lv and lv >= v.lv[1] and lv <= v.lv[2] then
				offset = v.offset
				break
			end
		end
	end
	return offset
end
function worldMapDefine.createMonsterWithLevel(level, isDie)
	local cfg = worldMapDefine.getMonsterCfgByLevel(level)
	local monster
	if isDie then
		monster = display.newSprite("#" .. cfg.npcModel .. "_sw_ws_08.png")
	else
		monster = display.newSprite("#" .. cfg.npcModel .. "_dj_ws_01.png")
		local frames = display.newFrames(cfg.npcModel .. "_dj_" .. "ws" .. "_%.2d.png", 1, 8)
		local animation = display.newAnimation(frames, 1.2 / #frames)
		monster:playAnimationForever(animation)
	end
	return monster
end
function worldMapDefine.createCityImageWithLevel(cityLevel, factionType, cityImage, addOffset)
	local factionCtrl = SoraDGetCtrl("factionCtrl")
	factionType = FACTION_TYPE.FACTION_NORMAL
	cityImage = cityImage or display.newSprite("#Castle_lv1_base.png")
	local isShowWarLv, cityLevel = SoraDGetBuildWarLv(cityLevel)
	local imageArray = factionCtrl:getFactionWorldCastle(factionType, isShowWarLv, cityLevel)
	if cityLevel == 30 and factionType == FACTION_TYPE.FACTION_BYZANTINE then
		isShowWarLv = true
		cityLevel = 0
	end
	if isShowWarLv then
		local offsetPos = worldMapDefine.cityWarLvOffset[cityLevel]
		if offsetPos then
			if addOffset then
				local x = cityImage:getPositionX()
				local y = cityImage:getPositionY()
				cityImage:setPosition(cc.p(x + offsetPos.x, y + offsetPos.y))
			else
				cityImage:setPosition(offsetPos)
			end
		end
	end
	if imageArray then
		for i, v in ipairs(imageArray) do
			if i == 1 then
				cityImage:setSpriteFrame(display.newSpriteFrame(v))
			else
				local levelImage = display.newSprite("#" .. v)
				levelImage:setPosition(cc.p(cityImage:getContentSize().width / 2, cityImage:getContentSize().height / 2))
				cityImage:addChild(levelImage)
			end
		end
	end
	return cityImage
end
