function worldMapDefine.getAllianceBuildInfo(buildType)
	local buildInfo
	if 0 < buildType and buildType <= #worldMapDefine.allianceBuildArray then
		buildInfo = worldMapDefine.allianceBuildArray[buildType]
	end
	return buildInfo
end
local lineColor_self = cc.c3b(0, 255, 0)
local lineColor_leader = cc.c3b(255, 0, 255)
local lineColor_league = cc.c3b(30, 162, 255)
local lineColor_all = cc.c3b(0, 255, 255)
local lineColor_friend = cc.c3b(255, 255, 0)
local lineColor_enemy = cc.c3b(255, 0, 0)
local lineColor_normal = cc.c3b(250, 250, 250)
function worldMapDefine.getNormalManorLineColor(isSelfLeague, allianceRelationType)
	return lineColor_normal
end
function worldMapDefine.getSelfManorLineColor(isSelfLeague, allianceRelationType)
	return lineColor_self
end
function worldMapDefine.getLeaderManorLineColor(isSelfLeague, allianceRelationType)
	return lineColor_leader
end
_ENV, worldMapDefine.getLeagueManorLineColor = worldMapDefine, function(isSelfLeague, allianceRelationType)
	local lineColor = lineColor_normal
	if isSelfLeague or allianceRelationType == gMapAllianceRelationType.SELF then
		lineColor = lineColor_league
	elseif allianceRelationType == gMapAllianceRelationType.ALLY then
		lineColor = lineColor_all
	elseif allianceRelationType == gMapAllianceRelationType.FRIENDLY then
		lineColor = lineColor_friend
	elseif allianceRelationType == gMapAllianceRelationType.ENEMY then
		lineColor = lineColor_enemy
	end
	return lineColor
end
worldMapDefine[gMapMoveLineColor.moveLineColorWhite] = lineColor_normal
worldMapDefine[gMapMoveLineColor.moveLineColorGreen] = lineColor_self
worldMapDefine[gMapMoveLineColor.moveLineColorRed] = lineColor_enemy
worldMapDefine[gMapMoveLineColor.moveLineColorPurple] = lineColor_leader
worldMapDefine[gMapMoveLineColor.moveLineColorBlue] = lineColor_league
worldMapDefine[gMapMoveLineColor.moveLineColorYellow] = lineColor_friend
local worldMapDefine[gMapMoveLineColor.moveLineColorAzure], tableLineColor = lineColor_all, worldMapDefine
function worldMapDefine.getMoveLineColor(lineColorType)
	return tableLineColor[lineColorType] or lineColor_normal
end
local armyDesRead = include("armyDesRead")
local worldMapSoldierDef = include("worldMapSoldierDef")
for k, v in pairs(worldMapSoldierDef.pointsType) do
	worldMapDefine[k] = v
end
for k, v in pairs(worldMapSoldierDef.soldierType) do
	worldMapDefine[k] = v
end
worldMapDefine.armySize = worldMapSoldierDef.armySize
worldMapDefine.frameNum = worldMapSoldierDef.frameNum
function worldMapDefine.getSoliderFrameNum(soldierType, isFighting)
	local cfg = worldMapDefine.frameNum[soldierType]
	_UPVALUE2_ = nil
	;(nil)[1] = 8
	local (nil)[2], frames = 8, nil
	if cfg then
		if #cfg == 2 then
			_UPVALUE2_ = #cfg
			frames, (#cfg)[1] = #cfg, cfg[1]
			frames, (#cfg)[2] = #cfg, cfg[2]
		elseif #cfg == 4 then
			if isFighting then
				_UPVALUE2_ = #cfg
				;(#cfg)[1] = cfg[1]
				;(#cfg)[2] = cfg[2]
			end
			_UPVALUE2_ = #cfg
			frames, (#cfg)[1] = #cfg, cfg[3]
			frames, (#cfg)[2] = #cfg, cfg[4]
			frames = #cfg or nil
		end
	end
	return frames
end
function worldMapDefine.getSoliderModelType(soldierID, factionType)
	return armyDesRead.getModelType(soldierID, factionType)
end
function worldMapDefine.getSoliderImageNameByType(soldierType, factionType)
	return armyDesRead.getModelImage(soldierType, factionType)
end
function worldMapDefine.getSoliderImageSets()
	return SoraDGetCtrl("factionCtrl"):getWorldSoliderImageSets()
end
local npcconfigData = include("npcconfig")
function worldMapDefine.getMonsterCfgByLevel(level)
	for k, v in pairs(npcconfigData) do
		if v.npcLevel == level and math.floor(v.npcId / 100) == 30 then
			return v
		end
	end
end
function worldMapDefine.getMonsterImageName(monsterClassID)
	local monsterData = npcconfigData[monsterClassID]
	return monsterData.npcModel
end
function worldMapDefine.getMonsterBustImageName(monsterClassID)
	local monsterData = npcconfigData[monsterClassID]
	return monsterData.npcImage
end
function worldMapDefine.getMonsterName(monsterClassID)
	local monsterData = npcconfigData[monsterClassID]
	local monsterName = i18n(monsterData.npcName)
	return monsterName
end
function worldMapDefine.getMonsterLevel(monsterClassID)
	local monsterData = npcconfigData[monsterClassID]
	return monsterData.npcLevel
end
function worldMapDefine.getMonsterIconLod(monsterClassID)
	local monsterData = npcconfigData[monsterClassID]
	return monsterData.iconLod
end
function worldMapDefine.getMaxMonsterLevel()
	local maxLv = 1
	for k, v in pairs(npcconfigData) do
		if maxLv < v.npcLevel then
			maxLv = v.npcLevel
		end
	end
	return maxLv
end
function worldMapDefine.getMonsterReward(monsterClassID)
	local monsterData = npcconfigData[monsterClassID]
	return monsterData.reward
end
function worldMapDefine.getMonstertalk(monsterClassID, index)
	local monsterData = npcconfigData[monsterClassID]
	local npcName = monsterData.npcModel
	if not index then
		math.randomseed(tostring(os.time()):reverse():sub(1, 6))
		local talkCount = monsterData.talk > 0 and monsterData.talk or 7
		index = math.random(talkCount)
	end
	local talk = string.format("Npc_talk_%s_%02d", npcName, index)
	local talkString = i18n(talk)
	return talkString
end
function worldMapDefine.checkIsWastelandMonster(monsterClassID)
	return monsterClassID and 3143 <= monsterClassID and monsterClassID <= 3152
end
