local chestpackconfig = include("chestpackconfig")
function worldMapDefine.getChestpackReward(lv)
	if not chestpackconfig[lv] then
		local chestpackconfig, chestpackData = chestpackconfig[lv], chestpackconfig[lv]
	end
	return chestpackData.reward
end
local worldbossconfig = include("worldbossconfig")
function worldMapDefine.getWorldBossReward(classID, lv)
	local _ENV, reward
	for k, v in ipairs(worldbossconfig) do
		if v.type == classID and v.level == lv then
			reward = v.reward
			break
		end
	end
	return reward
end
local worldbossdate = include("worldbossdate")
function worldMapDefine.isWorldBossCanAttackAlone(bossType, lv)
	for k, v in ipairs(worldbossdate) do
		if v.bossType == bossType and v.level == lv then
			return v.canAttackDirect == 1
		end
	end
	return false
end
function worldMapDefine.getWorldBossStamina(bossType, lv)
	for k, v in ipairs(worldbossdate) do
		if v.bossType == bossType and v.level == lv then
			return v.stamina
		end
	end
	return 20
end
function worldMapDefine.getWorldBossShield(bossType, lv)
	for k, v in ipairs(worldbossdate) do
		if v.bossType == bossType and v.level == lv then
			return v.shield
		end
	end
	return 20
end
function worldMapDefine.getWorldBossRemoveAfterSec(bossType, lv)
	for __, v in ipairs(worldbossdate) do
		if v.bossType == bossType and (not lv or v.level == lv) then
			return v.removeAfterSec
		end
	end
	return 0
end
local worldBossType = include("world_boss_type")
function worldMapDefine.getBossMaxAttackNum(bossType)
	local num = 0
	for k, v in ipairs(worldBossType) do
		if v.type == bossType then
			num = v.maxAttackNum
			break
		end
	end
	return num
end
function worldMapDefine.getBossMaxKillNum(bossType)
	local num = 0
	for k, v in ipairs(worldBossType) do
		if v.type == bossType then
			num = v.maxKillNum
			break
		end
	end
	return num
end
local worldbossshow = include("worldbossshow")
function worldMapDefine.getBossImage()
	local _ENV, iamgeTab
	if worldMapDefine.isRemainsKingdomID() then
		local ret = _G.SoraDIsFileExistByKey("worldMapBossRemain")
		if ret then
			table.insert(iamgeTab, "worldMap/worldMapBossRemain")
		end
		local ret = _G.SoraDIsFileExistByKey("worldMapBossRemain2")
		if ret then
			table.insert(iamgeTab, "worldMap/worldMapBossRemain2")
		end
		return iamgeTab
	else
		local ret = _G.SoraDIsFileExistByKey("worldMapBossNormal")
		if ret then
			table.insert(iamgeTab, "worldMap/worldMapBossNormal")
			return iamgeTab
		end
	end
	table.insert(iamgeTab, "worldMap/worldMapBossIcon")
	return iamgeTab
end
function worldMapDefine.hasBossHdRes(bossID, lv)
	local testImageNmae
	if worldMapDefine.isRemainsKingdomID() then
		if gBossType.ruinsWarMyBoss == bossID or gBossType.ruinsWarZjssgBoss == bossID then
			testImageNmae = "my_dj_ws_01.png"
		else
			testImageNmae = "esboss_dj_ws_01.png"
		end
	elseif bossID then
		if bossID == gBossType.fireDragon1 or bossID == gBossType.fireDragon2 then
			return true
		end
		local bossData = worldMapDefine.getWorldBossShow(bossID, lv)
		testImageNmae = string.format("%s_dj_ws_01.png", bossData.effects)
	else
		testImageNmae = "albb_dj_wn_01.png"
	end
	return worldMapDefine.checkHasRes(testImageNmae)
end
function worldMapDefine.hasLmqbHdRes()
	local testImageNmae = "lmzh_gj_n_01.png"
	return worldMapDefine.checkHasRes(testImageNmae)
end
function worldMapDefine.hasLmqbNormalRes()
	local testImageNmae = "lmzh_gj_n.png"
	return worldMapDefine.checkHasRes(testImageNmae)
end
function worldMapDefine.checkHasRes(imageName)
	local sharedSpriteFrameCache = cc.SpriteFrameCache:getInstance()
	local frame = sharedSpriteFrameCache:getSpriteFrame(imageName)
	print("worldMapDefine.checkHasRes", frame, frame ~= nil, frame:isDefault(), imageName)
	if frame and not frame:isDefault() then
		return true
	end
end
function worldMapDefine.getWorldBossShow(bossType, lv)
	if bossType == gBossType.wastelandBoss then
		if lv then
			local wastelandCtrl = SoraDGetCtrl("wastelandCtrl")
			local config = wastelandCtrl:getBossConfigByLv(lv)
			local ret = clone(worldbossshow[bossType])
			_UPVALUE4_ = nil
			;(nil)[1] = "image"
			;(nil)[2] = "icon"
			;(nil)[3] = "effects"
			;(nil)[4] = "name"
			for i, v in ipairs(nil) do
				ret[v] = config[v]
			end
			return ret
		end
	elseif bossType == gBossType.monkeyBoss then
		_ENV = gBossType.monkeyBoss
		gBossType.monkeyBoss.iconLod = "lod_monkey.png"
		return gBossType.monkeyBoss
	end
	local worldbossshow = worldbossshow[bossType] or worldbossshow[1]
	return worldbossshow
end
function worldMapDefine.getWorldBossName(bossType, lv)
	if bossType == gBossType.wastelandBoss then
		local wastelandCtrl = SoraDGetCtrl("wastelandCtrl")
		return wastelandCtrl:getBossConfigByLv(lv).name
	end
	if bossType == gBossType.monkeyBoss then
		return i18n("worldboss_monkey_08")
	end
	local worldbossshow = worldbossshow[bossType] or worldbossshow[1]
	return worldbossshow.name
end
function worldMapDefine.getWorldBossImage(bossType, lv)
	local cfg = worldMapDefine.getWorldBossShow(bossType, lv)
	return cfg and cfg.image
end
local chestpackshow = include("chestpackshow")
function worldMapDefine.getChestpackShow(chestID)
	return chestpackshow[chestID] or chestpackshow[1]
end
local treasurebowlconfig = include("treasurebowlconfig")
local treasurebowlshow = include("treasurebowlshow")
function worldMapDefine.getTreasureBowlpackShow(chestID)
	return treasurebowlshow[chestID] or treasurebowlshow[1]
end
function worldMapDefine.getTreasureBowlpackReward(lv)
	if not treasurebowlconfig[lv] then
		local treasurebowlconfig, treasurebowlData = treasurebowlconfig[lv], treasurebowlconfig[lv]
	end
	return treasurebowlData.reward
end
