function worldMapDefine.getCastleSkinEffect(castleType)
	local node = display.newNode()
	node:setName("skinBgEffectNode")
	local data = worldMapDefine.castleSkinEffect[castleType]
	if data then
		if data.effect then
			local par_node = SoraDCreateEffectNode(data.effect.param, nil, true)
			par_node:addTo(node)
		end
		if data.imgs then
			for k, v in pairs(data.imgs) do
				local sprite = display.newSprite("#" .. v.png)
				sprite:setPosition(v.pos)
				sprite:addTo(node)
				SoraDFadeINOUT(sprite)
			end
		end
		if data.frames then
			for k, v in pairs(data.frames) do
				local sprite = display.newSprite("#" .. v.png)
				sprite:setPosition(v.pos)
				sprite:addTo(node)
				local frames = display.newFrames(v.format, v.from, v.to)
				local animation = display.newAnimation(frames, v.time / #frames)
				sprite:playAnimationForever(animation)
			end
		end
		if data.offset then
			node:setPosition(data.offset)
		end
		if data.actSprite then
			for k, v in pairs(data.actSprite) do
				local sprite = display.newSprite("#" .. v.png)
				sprite:setPosition(v.pos)
				sprite:addTo(node)
				_UPVALUE3_ = sprite
				sprite[1] = cca.moveBy(v.animationConfig[k].time, 0, v.animationConfig[k].offsetH)
				sprite[2] = cca.moveBy(v.animationConfig[k].time, 0, -v.animationConfig[k].offsetH)
				sprite[3] = cca.moveBy(v.animationConfig[k].time, 0, -v.animationConfig[k].offsetH)
				sprite[4] = cca.moveBy(v.animationConfig[k].time, 0, v.animationConfig[k].offsetH)
				sprite[5] = cca.moveBy(v.animationConfig[k].time, 0, v.animationConfig[k].offsetH)
				sprite[6] = cca.moveBy(v.animationConfig[k].time, 0, v.animationConfig[k].offsetH)
				sprite[7] = cca.moveBy(v.animationConfig[k].time, 0, v.animationConfig[k].offsetH)
				local seq = cca.seq(sprite)
				sprite:runAction(cc.RepeatForever:create(seq))
			end
		end
	end
	return node
end
