function worldMapDefine.getCastleFrame(castleModel, parent, target, skin)
	local cfg = worldMapDefine.castleSkinFrame[castleModel]
	if cfg then
		local effectName = "worldMapBuildEffect_" .. castleModel
		local sprite = parent:addFromInstanceCache(effectName, 1)
		if not sprite then
			sprite = display.newSprite(string.format(cfg.frames, cfg.beginFrame or 1))
			if cfg.blend then
				sprite:setBlendFunc(cfg.blend[1], cfg.blend[2])
			end
			sprite:setScale(cfg.scale or 1)
			local frames = display.newFrames(cfg.frames, cfg.beginFrame or 1, cfg.endFrame)
			local animation = display.newAnimation(frames, (cfg.tempFrame or 4) / 60)
			sprite:playAnimationForever(animation)
			sprite:addTo(target, 1)
			parent:setCitySkinName(sprite, effectName)
		end
		sprite:setPosition(cfg.offset)
		skin:setVisible(not cfg.hideSkin)
		return sprite
	end
	return nil
end
function worldMapDefine.getLegendLordBg(node)
	node = node or display.newNode()
	local image_bg = display.newSprite("#LegendaryKing_palace.png")
	image_bg:setPosition(cc.p(-95, 120))
	image_bg:addTo(node, 1)
	return node
end
