function worldMapDefine.getSqueueIcon(moveLineType, mapType, troop)
	local iconName = "icon_map_battle.png"
	local scale = 1
	local _ENV, paramData
	local remainTime = troop:getStatusRemainTime()
	local totalTime = troop:getOrgStatusTotalTime()
	if troop:getEventType() == gMapEventTypeDef.mapEventTypeMapInstance then
		if moveLineType == gMapMoveLineType.moveLineTypeScout then
			iconName = "icon_map_operate_12.png"
			paramData.statusText = i18n("common_text_007")
			paramData.totalTime = totalTime
			paramData.leftTime = remainTime
		elseif moveLineType == gMapMoveLineType.moveLineTypeEscortHelp or moveLineType == gMapMoveLineType.moveLineTypeEscort then
			iconName = "icon_map_convey.png"
			if mapType == gMapObjTypeDef.mapObjTypePlayer and moveLineType == gMapMoveLineType.moveLineTypeEscortHelp then
				paramData.statusText = i18n("common_text_2470")
			else
				paramData.statusText = moveLineType == gMapMoveLineType.moveLineTypeEscortHelp and i18n("common_text_2339") or i18n("common_text_2352")
			end
			paramData.totalTime = totalTime
			paramData.leftTime = remainTime
		elseif mapType == gMapObjTypeDef.mapObjTypeTreasure then
			iconName = "icon_map_mineral_collect.png"
			paramData.statusText = i18n("common_text_1647")
			paramData.totalTime = totalTime
			paramData.leftTime = remainTime
		elseif mapType == gMapObjTypeDef.mapTypeFireTreasure then
			iconName = "icon_map_mineral_collect.png"
			paramData.statusText = i18n("common_text_830")
			paramData.totalTime = totalTime
			paramData.leftTime = remainTime
		elseif mapType == gMapObjTypeDef.mapObjTypeRelics then
			iconName = "icon_map_operate_08.png"
			paramData.statusText = i18n("common_text_831")
			paramData.totalTime = totalTime
			paramData.leftTime = remainTime
		elseif mapType == gMapObjTypeDef.desertMeteorite then
			iconName = "icon_map_operate_08.png"
			paramData.statusText = i18n("pickup_star_014")
			paramData.totalTime = totalTime
			paramData.leftTime = remainTime
		elseif moveLineType == gMapMoveLineType.moveLineTypeArmyHelp then
			iconName = "icon_map_operate_06.png"
			paramData.midText = tostring(troop.to.x) .. "," .. tostring(troop.to.y)
			paramData.midColor = cc.c3b(145, 145, 145)
			paramData.statusText = i18n("common_text_010")
			paramData.hideBtn = true
		elseif moveLineType == gMapMoveLineType.moveLineTypeResourceHelp then
			iconName = "icon_alliance_merchant.png"
		elseif moveLineType == gMapMoveLineType.moveLineTypeRelicsExplore then
			iconName = "icon_map_operate_08.png"
		elseif moveLineType == gMapMoveLineType.moveLineTypeDesertMeteorite then
			iconName = "icon_map_operate_08.png"
		elseif mapType == gMapObjTypeDef.mapObjTypeResource then
			if troop.to and troop.to.objId then
				iconName = worldMapDefine.getResourceIconName(troop.to.objId)
			else
				iconName = "btn_map_res.png"
			end
			paramData.statusText = i18n("common_text_830")
			paramData.totalTime = totalTime
			paramData.leftTime = remainTime
		elseif mapType == gMapObjTypeDef.mapTypeWarTreasure then
			if troop.to and troop.to.objId then
				iconName = worldMapDefine.getWarTreasureBuildingIcon(troop.to.objId)
			else
				iconName = "btn_map_res.png"
			end
			paramData.statusText = i18n("common_text_830")
			paramData.totalTime = totalTime
			paramData.leftTime = remainTime
		elseif mapType == gMapObjTypeDef.mapObjTypeCampsite or mapType == gMapObjTypeDef.mapTypePlain then
			iconName = "icon_map_operate_10.png"
			paramData.midText = tostring(troop.to.x) .. "," .. tostring(troop.to.y)
			paramData.midColor = cc.c3b(145, 145, 145)
			paramData.statusText = i18n("common_text_832")
			paramData.hideBtn = true
		elseif moveLineType == gMapMoveLineType.moveLineTypeSuperRes then
			if troop.to then
				local allianceDesRead = include("allianceDesRead")
				local idArray = SoraDStringsSplit(troop.to.id, "_")
				iconName = allianceDesRead.getBuildMiniIcon(tonumber(idArray[2]))
			end
			if troop:isTargetBuilding() then
				paramData.statusText = i18n("common_text_043")
			else
				paramData.statusText = i18n("common_text_830")
			end
			paramData.totalTime = totalTime
			paramData.leftTime = remainTime
		elseif mapType == gMapObjTypeDef.mapObjTypeBattlefieldSite or mapType == gMapObjTypeDef.mapObjTypeBattery or mapType == gMapObjTypeDef.mapTypeATBuilding or mapType == gMapObjTypeDef.mapObjTypeFortress or mapType == gMapObjTypeDef.mapObjTypeLegendLord or mapType == gMapObjTypeDef.mapObjTypeRemainsWar or mapType == gMapObjTypeDef.mapObjNewTrialCity or mapType == gMapObjTypeDef.mapTypeRadianceWarPalace or mapType == gMapObjTypeDef.mapTypeRadianceWarGate or mapType == gMapObjTypeDef.mapTypeRadianceWarBeacon or mapType == gMapObjTypeDef.mapObjTypeCastale then
			if moveLineType == gMapMoveLineType.moveLineTypecapture then
				local posX = troop.x or troop.to.x
				local posY = troop.y or troop.to.y
				if mapType == gMapObjTypeDef.mapObjTypeBattery then
					local palaceInfoRead = include("palaceInfoRead")
					iconName = palaceInfoRead.getBatteryIcon(troop.to.objId)
					scale = 1.5
				elseif mapType == gMapObjTypeDef.mapObjTypeFortress then
					iconName = "icon_alliance_fort.png"
				elseif mapType == gMapObjTypeDef.mapObjTypeLegendLord then
					if troop.to and troop.to.objId then
						local hegemonRead = include("hegemonRead")
						iconName = hegemonRead.getIcon(troop.to.objId)
					else
						iconName = "icon_world_legendaryking.png"
					end
				elseif mapType == gMapObjTypeDef.mapObjTypeRemainsWar then
					if troop.to and troop.to.objId then
						local remainsWarRead = include("remainsWarRead")
						iconName = remainsWarRead.getBuildIcon(troop.to.objId)
					end
				elseif mapType == gMapObjTypeDef.mapTypeRadianceWarPalace or mapType == gMapObjTypeDef.mapTypeRadianceWarGate or mapType == gMapObjTypeDef.mapTypeRadianceWarBeacon then
					local radianceWarRead = include("radianceWarRead")
					iconName = radianceWarRead.getBuildIcon(mapType)
				elseif mapType == gMapObjTypeDef.mapObjNewTrialCity then
					if troop.to and troop.to.objId then
						if troop.to.objId == 1 then
							iconName = "icon_alliancewar_defender.png"
						else
							iconName = "icon_alliance_battery.png"
						end
					end
				elseif mapType == gMapObjTypeDef.mapObjTypeCastale then
					local gametop = gModuleMgr.getObject("gametop")
					local KWKingdomCtrl = gametop.playertop_:getModule("KWKingdomCtrl")
					local bigCastale = KWKingdomCtrl:getKingdomCastaleModel()
					local palaceInfoRead = include("palaceInfoRead")
					iconName = palaceInfoRead.getIcon(bigCastale)
					scale = 1.2
				elseif mapType == gMapObjTypeDef.mapObjTypeBattlefieldSite then
					local buildType = troop:getToSubMapType()
					iconName = worldMapDefine.getPyramidbuildingIcon(buildType)
				elseif troop.remainTime == 0 then
					iconName = "icon_alliancewar_defender.png"
				end
				paramData.midText = tostring(posX) .. "," .. tostring(posY)
				paramData.midColor = cc.c3b(145, 145, 145)
				paramData.statusText = i18n("common_text_1461")
				paramData.hideBtn = true
			elseif moveLineType == gMapMoveLineType.moveLineTypeMass then
				if troop.remainTime == 0 then
					iconName = "icon_alliancewar_defender.png"
				end
				paramData.statusText = i18n("common_text_299")
				paramData.totalTime = totalTime
				paramData.leftTime = remainTime
			end
		elseif mapType == gMapObjTypeDef.mapObjTypeSuperResource then
			if troop:isTargetBuilding() then
				paramData.statusText = i18n("common_text_043")
			else
				paramData.statusText = i18n("common_text_830")
			end
			paramData.totalTime = totalTime
			paramData.leftTime = remainTime
		elseif mapType == gMapObjTypeDef.mapObjTypeKingdomLevelBuild then
			paramData.midText = tostring(troop.to.x) .. "," .. tostring(troop.to.y)
			paramData.midColor = cc.c3b(145, 145, 145)
			paramData.statusText = i18n("common_text_010")
			paramData.hideBtn = true
		elseif mapType == gMapObjTypeDef.mapObjTypeAllianceBuild then
			if moveLineType == gMapMoveLineType.moveLineTypeArmyHelp then
				paramData.midText = tostring(troop.to.x) .. "," .. tostring(troop.to.y)
				paramData.midColor = cc.c3b(145, 145, 145)
				paramData.statusText = i18n("common_text_010")
				paramData.hideBtn = true
			elseif moveLineType == gMapMoveLineType.moveLineTypeMass then
				paramData.statusText = i18n("common_text_299")
				paramData.totalTime = totalTime
				paramData.leftTime = remainTime
			end
		elseif mapType == gMapObjTypeDef.feast2024 then
			iconName = "icon_alliance_merchant.png"
		end
	elseif troop:getEventType() == gMapEventTypeDef.mapEventTypeTroopInstance then
		if troop.moveLineModel == gMapMoveLineModel.moveLineModelGoOut then
			paramData.statusText = i18n("common_text_481")
			paramData.totalTime = totalTime
			paramData.leftTime = remainTime
		elseif troop.moveLineModel == gMapMoveLineModel.moveLineModelGoBack then
			paramData.statusText = i18n("common_text_006")
			paramData.totalTime = totalTime
			paramData.leftTime = remainTime
		end
	end
	if moveLineType == gMapMoveLineType.moveLineTypeAttackLord then
		iconName = "icon_map_operate_02.png"
		if mapType == gMapObjTypeDef.mapObjTypeNpc or mapType == gMapObjTypeDef.nebulaNpc or mapType == gMapObjTypeDef.mapTypeMonsterFiesta then
			iconName = "icon_duilie_daguai.png"
		elseif mapType == gMapObjTypeDef.mapTypeWrathBeast then
			iconName = "icon_sjdi_xingjunjilu_long.png"
		end
		if troop.isDuel then
			iconName = "icon_map_Battle_43.png"
		end
		paramData.statusText = i18n("common_text_481")
		paramData.totalTime = totalTime
		paramData.leftTime = remainTime
	elseif moveLineType == gMapMoveLineType.moveLineTypeMass then
		if troop.isMainQueue then
			iconName = "icon_mass_blue.png"
		else
			iconName = "icon_map_mass.png"
		end
		if mapType == gMapObjTypeDef.mapTypeWrathBeast then
			iconName = "icon_sjdi_xingjunjilu_long.png"
		end
		paramData.statusText = i18n("common_text_299")
		paramData.totalTime = totalTime
		paramData.leftTime = remainTime
	end
	return iconName, scale, paramData
end
function worldMapDefine.getWorldMapViewClassType()
	local currentScene = display.getRunningScene()
	if currentScene.name == "MainScene" then
		local currentView = currentScene:currentSceneShowView()
		if currentView.__cname == "worldMapView" then
			return currentView.mapClassType
		end
	end
end
function worldMapDefine.getWorldMapView()
	local currentScene = display.getRunningScene()
	if currentScene.name == "MainScene" then
		local currentView = currentScene:currentSceneShowView()
		if currentView.__cname == "worldMapView" then
			return currentView
		end
	end
end
function worldMapDefine.getTotalDevilValleyArmyNum()
	local DC = require_data("devilvalley_config", true)
	local challengeLv = SoraDGetCtrl("devilValleyCtrl"):getMyTeams().challengeLv
	local info = DC.data[challengeLv].CastleArmyType
	local maxSize = #info
	local maxArmyNum = 0
	for i = 1, maxSize, 2 do
		maxArmyNum = maxArmyNum + info[i + 1]
	end
	return maxArmyNum
end
function worldMapDefine.isInAnchorMode()
	return false
end
function worldMapDefine.isSwitchAnchorMode()
	return false
end
function worldMapDefine.isCanSwitchToAnchor(noStatus)
	return false
end
function worldMapDefine.doSwitchToAnchor()
	if worldMapDefine.isSwitchAnchorMode() and not worldMapDefine.isInAnchorMode() then
		local anchorSwitch = include("anchorSwitch")
		anchorSwitch.doSwitch(true)
	end
end
function worldMapDefine.createWorldMapProtect(isGreen)
	local node = display.newNode()
	local setVisible = node.setVisible
	local _createEffect = function()
		local effect = SoraDCreatAnimation("worldMapProtect")
		local sp_outside = SoraDGetChildByName(effect, "dh_Texture_sstshd_001_9")
		local sp_inside = SoraDGetChildByName(effect, "dh_Texture_XL_sstshd_000_02")
		_UPVALUE2_ = "dh_Texture_XL_sstshd_000_02"
		;("dh_Texture_XL_sstshd_000_02")[1] = sp_outside
		;("dh_Texture_XL_sstshd_000_02")[2] = sp_inside
		for _, widget in pairs("dh_Texture_XL_sstshd_000_02") do
			widget:setGroupID(worldMapDefine.GROU_ID.group_protect_new)
			_G.SoraDMixtureGLONE(widget)
		end
		return effect
	end
	function node.setGreenColor(_, _isGreen)
		if node._effect then
			local sp_outside = SoraDGetChildByName(node._effect, "dh_Texture_sstshd_001_9")
			local sp_inside = SoraDGetChildByName(node._effect, "dh_Texture_XL_sstshd_000_02")
			if _isGreen then
				sp_outside:setColor(cc.c3b(89, 167, 255))
				sp_inside:setColor(cc.c3b(30, 112, 240))
			else
				sp_outside:setColor(cc.c3b(255, 255, 80))
				sp_inside:setColor(cc.c3b(255, 180, 76))
			end
		end
	end
	function node.setVisible(_, show)
		if show then
			if not node._effect then
				node._effect = _createEffect()
				node:setGreenColor(isGreen)
				node._effect:addTo(node)
			end
			if node._effect then
				node._effect:resume()
			end
		elseif node._effect then
			node._effect:pause()
		end
		setVisible(node, show)
	end
	return node
end
function worldMapDefine.createWorldMapProtectNew(isGray)
	local node = display.newNode()
	local setVisible = node.setVisible
	if isGray ~= nil then
		node._isGray = isGray
	else
		node._isGray = false
	end
	local _createEffect = function(isGray)
		local imageKey = "T_XL_Tex_xsbhz01_%03d.png"
		if isGray then
			imageKey = "T_XL_Tex_zcqcbhz01_%03d.png"
		end
		local sprite = display.newSprite("#" .. string.format(imageKey, 0))
		sprite:setContentSize(cc.size(205, 174))
		sprite:setPosition(0, 5)
		sprite:setScale(1.76)
		local spriteFrames = display.newFrames(imageKey, 0, 20)
		local animation = display.newAnimation(spriteFrames, 0.08333333333333333)
		sprite:playAnimationForever(animation)
		sprite:setGroupID(worldMapDefine.GROU_ID.group_protect_new)
		return sprite
	end
	function node.setIsGray(_, isGray)
		if node._isGray == isGray then
			return
		end
		node._isGray = isGray
		if node._effect then
			node._effect:removeFromParent()
			node._effect = nil
		end
	end
	function node.setVisible(_, show)
		if show then
			if not node._effect then
				node._effect = _createEffect(node._isGray)
				node._effect:addTo(node)
			end
			if node._effect then
				node._effect:resume()
			end
		elseif node._effect then
			node._effect:pause()
		end
		setVisible(node, show)
	end
	return node
end
