end).zi, (225).rotation, ("app.game.worldMap.meshData.zi_meshData")[2] = function(isGray)
	local node = display.newNode()
	local setVisible = node.setVisible
	if isGray ~= nil then
		node._isGray = isGray
	else
		node._isGray = false
	end
	local _createEffect = function(isGray)
		local imageKey = "T_XL_Tex_xsbhz01_%03d.png"
		if isGray then
			imageKey = "T_XL_Tex_zcqcbhz01_%03d.png"
		end
		local sprite = display.newSprite("#" .. string.format(imageKey, 0))
		sprite:setContentSize(cc.size(205, 174))
		sprite:setPosition(0, 5)
		sprite:setScale(1.76)
		local spriteFrames = display.newFrames(imageKey, 0, 20)
		local animation = display.newAnimation(spriteFrames, 0.08333333333333333)
		sprite:playAnimationForever(animation)
		sprite:setGroupID(worldMapDefine.GROU_ID.group_protect_new)
		return sprite
	end
	function node.setIsGray(_, isGray)
		if node._isGray == isGray then
			return
		end
		node._isGray = isGray
		if node._effect then
			node._effect:removeFromParent()
			node._effect = nil
		end
	end
	function node.setVisible(_, show)
		if show then
			if not node._effect then
				node._effect = _createEffect(node._isGray)
				node._effect:addTo(node)
			end
			if node._effect then
				node._effect:resume()
			end
		elseif node._effect then
			node._effect:pause()
		end
		setVisible(node, show)
	end
	return node
end, 225, "app.game.worldMap.meshData.zi_meshData", -25
