function worldMapDefine.point2tile(p1, p0, w, h)
	local p = cc.pSub(p1, p0)
	local tilex = (p.x * h - p.y * w) / (h * w)
	local tiley = (-p.x * h - p.y * w) / (h * w)
	local tile = cc.p(math.floor(tilex), math.floor(tiley))
	return tile
end
function worldMapDefine.point2tileRounding(p1, p0, w, h)
	local p = cc.pSub(p1, p0)
	local tilex = (p.x * h - p.y * w) / (h * w)
	local tiley = (-p.x * h - p.y * w) / (h * w)
	local tile = cc.p(math.floor(tilex + 0.5), math.floor(tiley + 0.5))
	return tile
end
function worldMapDefine.tile2point(p0, tile, w, h)
	local x = p0.x + (tile.x - tile.y) * w / 2
	local y = p0.y + -(tile.x + tile.y) * h / 2
	local point = cc.p(x, y)
	return point
end
function worldMapDefine.point2tileRounding_fgui(p1, p0, w, h)
	local _p1 = cc.p(p1.x, -p1.y)
	local _p0 = cc.p(p0.x, -p0.y)
	return worldMapDefine.point2tileRounding(_p1, _p0, w, h)
end
function worldMapDefine.tile2point_fgui(p0, tile, w, h)
	return worldMapDefine.tile2point(p0, tile, w, -h)
end
