worldMapDefine.warBarrageCfg, (function(mapObjType, worldMapTipButtonType, toPoint, isJoinMass)
	local gametop = gModuleMgr.getObject("gametop")
	local mapId = gametop.playertop_:getMapID()
	_ENV = gametop.playertop_
	local _ENV, gametop.playertop_.mapType, mapObj = nil, mapObjType, gametop.playertop_
	;(nil).to = toPoint
	local (nil).isJoinMass, data = isJoinMass, nil
	local moveLineType = worldMapFunction.getMoveLineTypeAndMatrixType(worldMapTipButtonType, toPoint)
	print("moveLineType, =  ", moveLineType)
	local mapObjUtil = include("mapObjUtil")
	if mapObjUtil.isWarBuild(mapObjType) and (moveLineType == gMapMoveLineType.moveLineTypeAttackLord or moveLineType == gMapMoveLineType.moveLineTypeArmyHelp) then
		moveLineType = gMapMoveLineType.moveLineTypecapture
	end
	local queueType = worldMapFunction.convertType(moveLineType, mapObj, data, mapId, nil, nil)
	return queueType
end)[gKingdomClassType.nebula], ("nebula").showArea, ("Game:nebulaWar:barrageSetting~table")[1] = function(mapObjType, worldMapTipButtonType, toPoint, isJoinMass)
